//! `Dataset.observe` / `Observation` against the classic leg of
//! `tests/fixtures/spark-4.2.0/observe-goldens.json` (real Spark 4.2.0 runs, generated by
//! `tests/scripts/gen_observe_goldens.py`; P3-T084). Every fixture case is either run here
//! (`cases`), run by the Python tests because the client raises it (`CLIENT_ONLY`), or listed in
//! `KNOWN_GAPS` with the reason it is not matched yet: a gap's case must still fail, so a fix
//! removes it from the list (the `window_range_month_goldens.rs` pattern). The Connect leg runs
//! through the server in `krishiv-connect-server/tests/execute.rs`.
#![cfg(test)]

use std::sync::Arc;
use std::time::Duration;

use arrow_array::cast::AsArray;
use arrow_array::types::{Decimal128Type, Float64Type, Int8Type, Int16Type, Int32Type, Int64Type};
use arrow_array::{Array, ArrayRef, Float64Array, Int32Array, RecordBatch, StringArray};
use arrow_schema::{DataType, Field, Schema};
use futures::executor::block_on;
use krishiv_common::error::KrishivError;
use krishiv_session::functions::{col, count, expr, lit, max, sum};
use krishiv_session::{Column, DataFrame, ExplainMode, JoinType, Observation, Session};
use serde_json::{Map, Value, json};

/// Cases the Python client raises before the engine is reached (`python/tests/test_observe.py`)
/// or that describe a PySpark class's attributes.
const CLIENT_ONLY: &[(&str, &str)] = &[
    (
        "anonymous_observation",
        "reads the Python Observation's private name",
    ),
    ("python_attrs", "attributes of PySpark's Observation class"),
    (
        "err_empty_observation_name",
        "VALUE_NOT_NON_EMPTY_STR is the Python client's",
    ),
    (
        "err_get_before_observe",
        "NO_OBSERVE_BEFORE_GET is the Python client's (the engine's KRISHIV_NO_OBSERVE_BEFORE_GET is tested in observe.rs)",
    ),
    (
        "err_reuse",
        "REUSE_OBSERVATION is the Python client's (KRISHIV_OBSERVATION_REUSED is tested in observe.rs)",
    ),
    ("err_no_exprs", "CANNOT_BE_EMPTY is the Python client's"),
    (
        "err_no_exprs_string",
        "CANNOT_BE_EMPTY is the Python client's",
    ),
    (
        "err_observation_name_type",
        "NOT_EXPECTED_TYPE is the Python client's",
    ),
    (
        "limit_zero",
        "classic Spark fails in the JVM here (an AssertionError in toPyRow); the Connect leg gives {}, run through the server",
    ),
];

/// Cases the engine does not match yet. Each must still fail; remove it when it passes.
const KNOWN_GAPS: &[(&str, &str)] = &[
    (
        "observation_through_sort_limit_topn",
        "Spark's TakeOrderedAndProject pulls 20 of the 1000 rows (a partition-dependent count); the engine's top-N reads all 1000 (P3-T084c)",
    ),
    (
        "err_scalar_subquery",
        "Spark runs a scalar subquery in a metric; the engine refuses it with KRISHIV_UNSUPPORTED_FEATURE (P3-T084c)",
    ),
    (
        "ansi_on_overflow_sum",
        "Spark's metric aggregate saturates a long sum at 9223372036854775807 under ANSI; the engine raises ARITHMETIC_OVERFLOW (P3-T084c)",
    ),
];

/// Cases whose `metrics` are compared as a subset of the fixture's columns (the case leaves out
/// what depends on which of the parallel drivers' rows a `LIMIT` takes).
const SUBSET_METRICS: &[&str] = &["limit_big_range"];

/// The follow-up fixture (`observe-goldens-followup.json`, P3-T084c): section `section`, leg `leg`.
fn followup(leg: &str, section: &str) -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/spark-4.2.0/observe-goldens-followup.json"
    );
    let all: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    all[leg][section].clone()
}

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/spark-4.2.0/observe-goldens.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// A session over the generator's `base()`: `t(k string, v int, x double)`, ANSI on.
fn session() -> Session {
    let s = Session::new().unwrap();
    s.conf().set("spark.sql.ansi.enabled", "true").unwrap();
    let schema = Arc::new(Schema::new(vec![
        Field::new("k", DataType::Utf8, true),
        Field::new("v", DataType::Int32, true),
        Field::new("x", DataType::Float64, true),
    ]));
    let batch = RecordBatch::try_new(
        Arc::clone(&schema),
        vec![
            Arc::new(StringArray::from(vec![Some("a"), Some("b"), Some("c")])) as ArrayRef,
            Arc::new(Int32Array::from(vec![Some(1), Some(2), None])),
            Arc::new(Float64Array::from(vec![Some(1.5), None, Some(3.0)])),
        ],
    )
    .unwrap();
    s.register_batches("t", schema, vec![batch]).unwrap();
    s
}

fn base(s: &Session) -> DataFrame {
    s.table("t")
}

fn sql(s: &Session, text: &str) -> DataFrame {
    block_on(s.sql(text)).unwrap()
}

fn n() -> Column {
    count(lit(1)).alias("n")
}

fn e(text: &str) -> Column {
    expr(text).unwrap()
}

/// Python's `repr` of a float.
fn py_float(f: f64) -> String {
    if f.is_nan() {
        "nan".to_owned()
    } else if f.is_infinite() {
        if f > 0.0 { "inf" } else { "-inf" }.to_owned()
    } else if f == f.trunc() && f.abs() < 1e16 {
        format!("{f:.1}")
    } else {
        format!("{f}")
    }
}

/// One cell as the fixture writes values (`norm` in the generator).
fn cell(c: &ArrayRef, i: usize) -> Value {
    if c.is_null(i) {
        return Value::Null;
    }
    match c.data_type() {
        DataType::Boolean => Value::from(c.as_boolean().value(i)),
        DataType::Int8 => Value::from(c.as_primitive::<Int8Type>().value(i)),
        DataType::Int16 => Value::from(c.as_primitive::<Int16Type>().value(i)),
        DataType::Int32 => Value::from(c.as_primitive::<Int32Type>().value(i)),
        DataType::Int64 => Value::from(c.as_primitive::<Int64Type>().value(i)),
        DataType::Float64 => Value::from(py_float(c.as_primitive::<Float64Type>().value(i))),
        DataType::Utf8 => Value::from(c.as_string::<i32>().value(i)),
        DataType::Utf8View => Value::from(c.as_string_view().value(i)),
        DataType::Decimal128(_, scale) => {
            let raw = c.as_primitive::<Decimal128Type>().value(i);
            let scale = usize::try_from(*scale).unwrap();
            let digits = raw.unsigned_abs().to_string();
            let digits = format!("{digits:0>width$}", width = scale + 1);
            let (int, frac) = digits.split_at(digits.len() - scale);
            let sign = if raw < 0 { "-" } else { "" };
            let repr = if scale == 0 {
                format!("{sign}{int}")
            } else {
                format!("{sign}{int}.{frac}")
            };
            json!({"py_type": "Decimal", "repr": repr})
        }
        DataType::List(_) => {
            let list = c.as_list::<i32>().value(i);
            Value::Array((0..list.len()).map(|j| cell(&list, j)).collect())
        }
        DataType::Struct(_) => {
            let st = c.as_struct();
            Value::Array(
                (0..st.num_columns())
                    .map(|j| cell(st.column(j), i))
                    .collect(),
            )
        }
        other => panic!("unexpected metric type {other}"),
    }
}

/// The metrics row as a dict: a repeated name keeps its last column (Python's dict).
fn metrics(row: &RecordBatch) -> Value {
    let mut out = Map::new();
    for (i, f) in row.schema().fields().iter().enumerate() {
        out.insert(f.name().clone(), cell(row.column(i), 0));
    }
    Value::Object(out)
}

/// What `Observation.get` returns (`getres` in the generator), or `blocked` when no action has
/// finished.
fn got(o: &Observation) -> Value {
    match o.get_timeout(Duration::from_millis(400)) {
        Ok(Some(row)) => json!({"get": "ok", "metrics": metrics(&row)}),
        Ok(None) => json!({"get": "blocked"}),
        Err(e) => json!({"get": "error", "error": error(&e)}),
    }
}

fn error(e: &KrishivError) -> Value {
    json!({
        "errorClass": e.error_class().name(),
        "sqlState": e.sql_state(),
        "outcome": "error",
    })
}

#[expect(
    clippy::needless_pass_by_value,
    reason = "builders pass frames and values on"
)]
fn merged(mut a: Value, b: Value) -> Value {
    a.as_object_mut()
        .unwrap()
        .extend(b.as_object().unwrap().clone());
    a
}

fn counted(df: &DataFrame) -> Value {
    // An action's failure is the case's value, so the comparison (or a gap) reports it.
    match block_on(df.count()) {
        Ok(n) => json!(n),
        Err(e) => error(&e),
    }
}

/// `df.observe(o, metrics)`, the action, and what `get` holds (`run` in the generator).
#[expect(
    clippy::needless_pass_by_value,
    reason = "builders pass frames and values on"
)]
fn run(df: DataFrame, metrics_of: Vec<Column>, action: impl FnOnce(&DataFrame) -> Value) -> Value {
    let o = Observation::named("m").unwrap();
    let observed = df.observe(&o, metrics_of).unwrap();
    let result = action(&observed);
    let row = if result.is_null() {
        json!({})
    } else {
        json!({"action_result": result})
    };
    merged(row, got(&o))
}

fn count_action(d: &DataFrame) -> Value {
    counted(d)
}

/// An analysis or run error of `exprs` over `df`, or what `get` holds if it ran.
#[expect(
    clippy::needless_pass_by_value,
    reason = "builders pass frames and values on"
)]
fn err_case(df: DataFrame, exprs: Vec<Column>) -> Value {
    let o = Observation::named("m").unwrap();
    let observed = df.observe(&o, exprs).unwrap();
    match block_on(observed.count()) {
        Err(e) => error(&e),
        Ok(_) => merged(json!({"outcome": "ok_unexpected"}), got(&o)),
    }
}

type Case = fn(&Session) -> Value;

#[expect(clippy::too_many_lines, reason = "one table of the fixture's cases")]
fn cases() -> Vec<(&'static str, Case)> {
    vec![
        ("basic_alias", |s| {
            run(
                base(s),
                vec![
                    count(lit(1)).alias("rows"),
                    sum(col("v")).alias("sv"),
                    max(col("k")).alias("mk"),
                ],
                count_action,
            )
        }),
        ("no_alias_names", |s| {
            run(
                base(s),
                vec![
                    count(lit(1)),
                    max(col("v")),
                    sum(col("v") + lit(1)),
                    lit(42),
                ],
                count_action,
            )
        }),
        ("literal_only", |s| {
            run(
                base(s),
                vec![lit(42).alias("c"), lit("s").alias("s")],
                count_action,
            )
        }),
        ("composite_expr", |s| {
            run(
                base(s),
                vec![
                    (sum(col("v")) + e("avg(x)") - lit(1)).alias("e"),
                    e("count(*)").alias("n"),
                ],
                count_action,
            )
        }),
        ("empty_input", |s| {
            run(
                base(s).filter(lit(1).eq(0)),
                vec![
                    n().alias("c"),
                    sum(col("v")).alias("s"),
                    max(col("k")).alias("mx"),
                    e("avg(x)").alias("a"),
                    e("collect_list(k)").alias("l"),
                ],
                count_action,
            )
        }),
        ("empty_input_no_rows_collected", |s| {
            run(base(s).filter(lit(1).eq(0)), vec![n().alias("c")], |d| {
                let rows: usize = block_on(d.collect())
                    .unwrap()
                    .iter()
                    .map(RecordBatch::num_rows)
                    .sum();
                assert_eq!(rows, 0);
                json!([])
            })
        }),
        ("types", |s| {
            run(
                sql(
                    s,
                    "select cast(1.10 as decimal(5,2)) d, cast('NaN' as double) n, cast(-0.0 as double) z, 1 i",
                ),
                vec![
                    e("sum(d)").alias("sd"),
                    e("max(n)").alias("mn"),
                    e("min(z)").alias("mz"),
                    e("sum(i)").alias("si"),
                    e("avg(i)").alias("ai"),
                    e("collect_list(i)").alias("l"),
                    e("struct(max(i), min(i))").alias("st"),
                ],
                count_action,
            )
        }),
        ("nulls_all", |s| {
            run(
                sql(s, "select cast(null as int) v"),
                vec![
                    sum(col("v")).alias("s"),
                    count(col("v")).alias("c"),
                    max(col("v")).alias("m"),
                ],
                count_action,
            )
        }),
        ("aggregate_with_alias_inside_nested_alias", |s| {
            run(
                base(s),
                vec![sum(col("v")).alias("a").alias("b")],
                count_action,
            )
        }),
        ("observed_metric_column_name_collision", |s| {
            run(base(s), vec![n(), sum(col("v")).alias("n")], count_action)
        }),
        ("count_action_prunes_columns", |s| {
            run(base(s), vec![sum(col("v")).alias("s")], count_action)
        }),
        ("filter_after_observe", |s| {
            run(base(s), vec![n()], |d| counted(&d.filter(col("v").eq(1))))
        }),
        ("filter_before_observe", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).filter(col("v").eq(1)).observe(&o, [n()]).unwrap();
            block_on(df.collect()).unwrap();
            got(&o)
        }),
        ("exact_under_parallelism", |s| {
            run(
                s.range(0, 100_000, 1, Some(8)),
                vec![n(), sum(col("id")).alias("s"), max(col("id")).alias("mx")],
                count_action,
            )
        }),
        ("conditional_metric_no_raise_unselected", |s| {
            run(
                sql(s, "select * from values (0),(2) as t(v)"),
                vec![e("sum(case when v != 0 then 10 / v end)").alias("s")],
                count_action,
            )
        }),
        ("ansi_on_overflow_sum", |s| {
            let text = "select cast(9223372036854775807 as bigint) v union all select 1";
            match block_on(s.sql(text)) {
                Err(e) => json!({"stage": "sql", "error": error(&e)}),
                Ok(df) => run(df, vec![sum(col("v")).alias("s")], count_action),
            }
        }),
        ("ansi_off_overflow_sum", |s| {
            s.conf().set("spark.sql.ansi.enabled", "false").unwrap();
            run(
                sql(
                    s,
                    "select cast(9223372036854775807 as bigint) v union all select 1",
                ),
                vec![
                    sum(col("v")).alias("s"),
                    (max(col("v")) + lit(1)).alias("p1"),
                ],
                count_action,
            )
        }),
        ("ansi_on_cast_error_inside_metric", |s| {
            err_case(base(s), vec![e("sum(cast(k as int))").alias("s")])
        }),
        // limits: the rows a limit above takes are the rows counted
        ("limit_after_observe", |s| {
            run(base(s), vec![n()], |d| {
                block_on(d.limit(1).collect()).unwrap();
                Value::Null
            })
        }),
        ("take_after_observe", |s| {
            run(base(s), vec![n()], |d| {
                block_on(d.limit(1).collect()).unwrap();
                Value::Null
            })
        }),
        ("limit_big_range", |s| {
            let mut v = run(
                s.range(0, 100_000, 1, Some(4)),
                vec![n(), sum(col("id")).alias("s")],
                |d| {
                    block_on(d.limit(3).collect()).unwrap();
                    Value::Null
                },
            );
            // `s` sums the rows the racing drivers handed the limit (Spark: partition 0's rows).
            v["metrics"].as_object_mut().unwrap().remove("s");
            v
        }),
        ("show_action_limit20", |s| {
            run(s.range(0, 1000, 1, Some(4)), vec![n()], |d| {
                // `show(3)` reads `limit(4)`: one more row than it shows.
                block_on(d.limit(4).collect()).unwrap();
                Value::Null
            })
        }),
        ("observation_through_sort_limit_topn", |s| {
            run(s.range(0, 1000, 1, Some(4)), vec![n()], |d| {
                block_on(d.order_by([col("id")]).limit(5).collect()).unwrap();
                Value::Null
            })
        }),
        ("first_then_second_action", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).observe(&o, [n()]).unwrap();
            block_on(df.limit(1).collect()).unwrap();
            let first = got(&o)["metrics"].clone();
            block_on(df.count()).unwrap();
            let second = got(&o)["metrics"].clone();
            json!({"after_limit1": first, "after_count": second})
        }),
        ("multiple_actions_first_wins", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s)
                .observe(&o, [n(), sum(col("v")).alias("s")])
                .unwrap();
            let c1 = block_on(df.count()).unwrap();
            let after_first = got(&o);
            let c2 = block_on(df.filter(col("v").is_not_null()).count()).unwrap();
            let c3: usize = block_on(df.collect())
                .unwrap()
                .iter()
                .map(RecordBatch::num_rows)
                .sum();
            json!({"counts": [c1, c2, c3], "after_first": after_first, "after_more": got(&o)})
        }),
        ("get_blocks_without_action", |s| {
            let o = Observation::named("m").unwrap();
            base(s).observe(&o, [n()]).unwrap();
            got(&o)
        }),
        ("get_after_transformation_only_no_action_then_action", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).observe(&o, [n()]).unwrap();
            let before = got(&o);
            block_on(df.count()).unwrap();
            json!({"before_action": before, "after_action": got(&o)})
        }),
        ("explain_does_not_trigger", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).observe(&o, [n()]).unwrap();
            block_on(df.explain(ExplainMode::Simple)).unwrap();
            got(&o)
        }),
        ("observation_on_action_collect_schema_only", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).observe(&o, [n()]).unwrap();
            block_on(df.schema()).unwrap();
            json!({"get_after_schema": got(&o)})
        }),
        // caches
        ("cache", |s| {
            let o = Observation::named("m").unwrap();
            let df = base(s).observe(&o, [n()]).unwrap().cache();
            let a = block_on(df.count()).unwrap();
            let after_first = got(&o);
            let b = block_on(df.count()).unwrap();
            json!({"counts": [a, b], "after_first": after_first, "after_second": got(&o)})
        }),
        ("cache_then_new_observe_on_cached", |s| {
            let df = base(s).cache();
            block_on(df.count()).unwrap();
            let o = Observation::named("m").unwrap();
            block_on(df.observe(&o, [n()]).unwrap().collect()).unwrap();
            got(&o)
        }),
        // several nodes in one plan
        ("union_two_branches_distinct_names", |s| {
            let (oa, ob) = (
                Observation::named("a").unwrap(),
                Observation::named("b").unwrap(),
            );
            let a = base(s).observe(&oa, [n()]).unwrap();
            let b = base(s).filter(col("v").eq(1)).observe(&ob, [n()]).unwrap();
            json!({"count": counted(&a.union(&b)), "a": got(&oa), "b": got(&ob)})
        }),
        ("union_two_branches_same_name_diff_df", |s| {
            let a = base(s).observe_named("dup", [n()]);
            let b = base(s).observe_named("dup", [n()]);
            match block_on(a.union(&b).count()) {
                Err(e) => error(&e),
                Ok(_) => json!({"outcome": "ok_unexpected"}),
            }
        }),
        ("self_join_same_df", |s| {
            let o = Observation::named("m").unwrap();
            let d = base(s).observe(&o, [n()]).unwrap();
            let l = d.alias("l");
            let r = d.alias("r");
            let c = counted(&l.join(&r, l.col("k").eq(r.col("k")), JoinType::Inner));
            merged(json!({"count": c}), got(&o))
        }),
        ("self_union_same_df", |s| {
            let o = Observation::named("m").unwrap();
            let d = base(s).observe(&o, [n()]).unwrap();
            merged(json!({"count": counted(&d.union(&d))}), got(&o))
        }),
        ("join_two_observed", |s| {
            let (oa, ob) = (
                Observation::named("a").unwrap(),
                Observation::named("b").unwrap(),
            );
            let a = base(s).observe(&oa, [n()]).unwrap();
            let b = base(s).observe(&ob, [sum(col("v")).alias("s")]).unwrap();
            let c = counted(&a.join_using(&b, ["k"], JoinType::Inner));
            json!({"count": c, "a": got(&oa), "b": got(&ob)})
        }),
        ("same_name_string_same_df_in_both_branches", |s| {
            let d = base(s).observe_named("dup", [n()]);
            json!({"count": counted(&d.union(&d))})
        }),
        ("nested_observe_different_names", |s| {
            let (oa, ob) = (
                Observation::named("a").unwrap(),
                Observation::named("b").unwrap(),
            );
            let d = base(s)
                .observe(&oa, [n()])
                .unwrap()
                .filter(col("v").eq(1))
                .observe(&ob, [count(lit(1)).alias("m")])
                .unwrap();
            json!({"count": counted(&d), "a": got(&oa), "b": got(&ob)})
        }),
        ("nested_observe_same_name_diff_df", |s| {
            let d = base(s)
                .observe_named("dup", [n()])
                .filter(col("v").eq(1))
                .observe_named("dup", [n()]);
            match block_on(d.count()) {
                Err(e) => error(&e),
                Ok(_) => json!({"outcome": "ok_unexpected"}),
            }
        }),
        ("observation_in_groupby_downstream", |s| {
            let o = Observation::named("m").unwrap();
            let d = base(s)
                .observe(&o, [n()])
                .unwrap()
                .group_by([col("k")])
                .agg([count(lit(1))]);
            block_on(d.collect()).unwrap();
            got(&o)
        }),
        (
            "string_observe_returns_df_only",
            |s| json!({"count": counted(&base(s).observe_named("nm", [n()]))}),
        ),
        // failures
        ("failed_query", |s| {
            let o = Observation::named("m").unwrap();
            let d = s
                .range(0, 5, 1, None)
                .observe(&o, [n()])
                .unwrap()
                .select_expr(["1/(id-2) as r"])
                .unwrap();
            let action = match block_on(d.collect()) {
                Err(e) => error(&e),
                Ok(_) => json!("ok_unexpected"),
            };
            json!({"action": {"errorClass": action["errorClass"], "sqlState": action["sqlState"]}, "get": got(&o)["get"]})
        }),
        ("failed_query_then_reuse_df_succeeds", |s| {
            let o = Observation::named("m").unwrap();
            let d = s.range(0, 5, 1, None).observe(&o, [n()]).unwrap();
            drop(block_on(
                d.select_expr(["1/(id-2) as r"]).unwrap().collect(),
            ));
            let after_fail = got(&o)["get"].clone();
            block_on(d.count()).unwrap();
            json!({"after_fail": {"get": after_fail}, "after_success": {"get": got(&o)["get"]}})
        }),
        ("write_action", |s| {
            let o = Observation::named("m").unwrap();
            let d = base(s)
                .observe(&o, [n(), sum(col("v")).alias("s")])
                .unwrap();
            let dir = tempfile::tempdir().unwrap();
            block_on(d.write().parquet(dir.path().join("o").to_str().unwrap())).unwrap();
            got(&o)
        }),
        // metric analysis
        ("err_attribute", |s| err_case(base(s), vec![col("v")])),
        ("err_attribute_alias_mixed", |s| {
            err_case(base(s), vec![n().alias("c"), col("v").alias("raw")])
        }),
        ("err_nondeterministic_rand", |s| {
            err_case(base(s), vec![e("rand()").alias("r")])
        }),
        ("ok_nondeterministic_inside_agg", |s| {
            let v = err_case(base(s), vec![e("sum(rand())").alias("r")]);
            json!({"outcome": v["outcome"], "get": v["get"]})
        }),
        ("err_nondeterministic_plus_agg", |s| {
            err_case(base(s), vec![(n() + e("rand()")).alias("r")])
        }),
        ("err_nested_aggregate", |s| {
            err_case(base(s), vec![e("sum(max(v))").alias("n")])
        }),
        ("err_distinct", |s| {
            err_case(base(s), vec![e("count(distinct v)").alias("d")])
        }),
        ("err_distinct_sum", |s| {
            err_case(base(s), vec![e("sum(distinct v)").alias("d")])
        }),
        ("err_filter", |s| {
            err_case(base(s), vec![e("count(v) filter (where v > 1)").alias("f")])
        }),
        ("err_window", |s| {
            err_case(base(s), vec![e("sum(v) over (order by k)").alias("w")])
        }),
        ("err_generator", |s| {
            err_case(base(s), vec![e("explode(array(1, 2))").alias("g")])
        }),
        ("err_unresolved_column", |s| {
            err_case(base(s), vec![e("sum(nope)").alias("s")])
        }),
        ("err_scalar_subquery", |s| {
            err_case(
                base(s),
                vec![e("(select max(id) from range(3))").alias("s")],
            )
        }),
        ("ok_aggregate_over_subquery_free_udf_like", |s| {
            err_case(base(s), vec![e("sum(length(k))").alias("s")])
        }),
        ("err_unresolved_star", |s| {
            err_case(base(s), vec![e("count(*)").alias("c"), col("*")])
        }),
        ("ok_approx_count_distinct", |s| {
            err_case(base(s), vec![e("approx_count_distinct(v)").alias("a")])
        }),
        ("err_first_ignorenulls_ok", |s| {
            err_case(base(s), vec![e("first(v, true)").alias("f")])
        }),
        ("ok_count_if", |s| {
            err_case(base(s), vec![e("count_if(v > 0)").alias("c")])
        }),
        ("err_empty_name_string_api", |s| {
            let d = base(s).observe_named("", [n()]);
            match block_on(d.count()) {
                Err(e) => error(&e),
                Ok(_) => json!({"outcome": "ok_unexpected"}),
            }
        }),
    ]
}

/// `got` against `want`: every key `got` has must match (so a case compares the columns it
/// builds); a metrics dict must match key for key unless the case is in `SUBSET_METRICS`.
fn matches(got: &Value, want: &Value, subset: bool, key: &str) -> bool {
    match (got, want) {
        (Value::Object(g), Value::Object(w)) => {
            let exact = key == "metrics" && !subset;
            (!exact || g.len() == w.len())
                && g.iter()
                    .all(|(k, v)| w.get(k).is_some_and(|x| matches(v, x, subset, k)))
        }
        (Value::Array(g), Value::Array(w)) => {
            g.len() == w.len() && g.iter().zip(w).all(|(a, b)| matches(a, b, subset, key))
        }
        _ => got == want,
    }
}

fn outcome(name: &str, case: Case, want: &Value) -> Result<(), String> {
    // A panic inside a case (an unexpected `unwrap`) is that case's failure, with its name.
    let got =
        std::panic::catch_unwind(|| case(&session())).map_err(|_| format!("{name}: panicked"))?;
    let subset = SUBSET_METRICS.contains(&name);
    if matches(&got, want, subset, "") {
        Ok(())
    } else {
        Err(format!("{name}: got {got}\n   want {want}"))
    }
}

#[test]
fn every_fixture_case_is_run_skipped_or_a_known_gap() {
    let all = fixture();
    let classic = all["classic"].as_object().unwrap();
    let cases = cases();
    let mut seen: Vec<&str> = cases.iter().map(|(n, _)| *n).collect();
    seen.extend(CLIENT_ONLY.iter().map(|(n, _)| *n));
    let missing: Vec<&String> = classic
        .keys()
        .filter(|k| !seen.contains(&k.as_str()))
        .collect();
    assert!(
        missing.is_empty(),
        "fixture cases nothing runs: {missing:?}"
    );
    for name in seen {
        assert!(classic.contains_key(name), "{name} is not in the fixture");
    }
    for (name, _) in KNOWN_GAPS {
        assert!(
            cases.iter().any(|(n, _)| n == name),
            "gap {name} is not a case"
        );
    }
}

#[test]
fn classic_goldens_match_spark() {
    let all = fixture();
    let classic = all["classic"].as_object().unwrap();
    let mut failures = Vec::new();
    let mut fixed = Vec::new();
    for (name, case) in cases() {
        let result = outcome(name, case, &classic[name]);
        let gap = KNOWN_GAPS.iter().any(|(g, _)| *g == name);
        match (result, gap) {
            (Err(why), false) => failures.push(why),
            (Ok(()), true) => fixed.push(name),
            // What the gap looks like now (visible with `--nocapture`).
            (Err(why), true) => eprintln!("known gap: {why}"),
            _ => {}
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert!(
        fixed.is_empty(),
        "these known gaps now match Spark: remove them from KNOWN_GAPS: {fixed:?}"
    );
}

// ---- proven-empty shapes (`empty_shapes`, P3-T084c) ----

/// `range(0, 6)` as `v`, in two partitions (the generator's `base3`).
fn base3(s: &Session) -> DataFrame {
    s.range(0, 6, 1, Some(2)).select_expr(["id as v"]).unwrap()
}

fn never(df: &DataFrame) -> DataFrame {
    df.filter_expr("false").unwrap()
}

/// `build(observed base3)` run with `count()`; or `build` given the unobserved frame when the
/// case observes inside (`inside`).
fn empty_run(s: &Session, build: impl FnOnce(&DataFrame) -> DataFrame) -> Value {
    let o = Observation::named("m").unwrap();
    let observed = base3(s).observe(&o, [n()]).unwrap();
    let result = counted(&build(&observed));
    merged(json!({"action_result": result}), got(&o))
}

fn empty_inside(_s: &Session, inner: &DataFrame) -> Value {
    let o = Observation::named("m").unwrap();
    let observed = inner.observe(&o, [n()]).unwrap();
    merged(json!({"action_result": counted(&observed)}), got(&o))
}

